using System.Text.Json.Serialization;
using Fusion.Messaging.Kafka.Helpers;

namespace Fusion.Messaging.Kafka.Events;

/// <summary>
/// Represents a base class for events generated by Debezium, encapsulating the
/// state of an entity or record before and after a data change operation.
/// </summary>
/// <typeparam name="TLegacyEntity">The type of the entity or record being tracked in the event.</typeparam>
public class CdcEvent<TLegacyEntity> : ICdcEvent where TLegacyEntity : class
{
    /// <inheritdoc cref="ICdcEvent.CustomerId"/>
    public long CustomerId { get; set; }
    
    /// <summary>
    /// Gets or sets the state of the entity or record before the data change operation, providing
    /// a snapshot of the original values prior to the modification. This property can be null
    /// if the event does not include information about the previous state, such as in the case
    /// of insert operations.
    /// </summary>
    public TLegacyEntity? Before { get; set; }

    /// <summary>
    /// Gets or sets the state of the entity or record after the data change operation, providing
    /// a snapshot of the updated values following the modification. This property can be null
    /// if the event does not include information about the resulting state, such as in the case
    /// of delete operations.
    /// </summary>
    public TLegacyEntity? After { get; set; }

    /// <summary>
    /// Gets or sets metadata about the source of the data change event, including information
    /// such as the database, schema, table, and other related details. This property provides
    /// context for the origin of the event within the source system.
    /// </summary>
    public CdcSourceEvent Source { get; set; } = null!;

    /// <summary>
    /// Gets or sets the type of data change operation represented by the event. This property
    /// typically indicates whether the event corresponds to a create, update, or delete
    /// operation on the entity or record.
    /// </summary>
    [JsonConverter(typeof(CdcOperationConverter))]
    public CdcOperation Op { get; set; }
}